pub fn classify_t_primes(nums: Vec<u64>) -> Vec<bool> {
    let mut result = Vec::new();
    for &num in &nums {
        result.push(is_t_prime(num));
    }
    result
}

fn is_t_prime(n: u64) -> bool {
    if n <= 1 {
        return false;
    }

    let mut count = 0;
    let mut i = 1;
    while i * i <= n {
        if n % i == 0 {
            if i * i == n {
                count += 1;
            } else {
                count += 2;
            }
        }
        i += 1;
    }

    count == 3
}
